import RNA, random, time, sys, os
from multiprocessing import Pool

target = "((..(((..((((..((....((..((((....))....))..))))..))....))..))((..((..((..((((..((....((..((((..((....((....))))..))....))..))))..))((..((..((....))((..((((..((....((..((((....))....))..))))..))....))..))))..))..))..))((..((....((..((((..((....((....))))..))....))..))))..))))..))..)..))"
n = len(target)
pair = [-1]*n
stack = []
for i,c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pair[i] = j; pair[j] = i
paired_i = [i for i in range(n) if pair[i]>i]
unpaired = [i for i in range(n) if pair[i]==-1]
comp = {'G':'C','C':'G','A':'U','U':'A'}
loops = [(29,32),(103,106),(141,144),(171,174),(245,248)]
loopset = set()
for a,b in loops:
    loopset.update([a,a+1,a+2,a+3])

def init_seq():
    seq=['A']*n
    for i in paired_i:
        seq[i]='G'; seq[pair[i]]='C'
    for a,b in loops:
        seq[a]='G';seq[a+1]='A';seq[a+2]='A';seq[a+3]='A'
        cp_i=a-1;cp_j=b+1
        if pair[cp_i]==cp_j:
            seq[cp_i]='C'; seq[cp_j]='G'
    return seq

def fold(s):
    fc=RNA.fold_compound(s); mfe,_=fc.mfe(); return mfe

def score_struct(mfe):
    return sum(1 for x,y in zip(mfe,target) if x!=y)

def search_worker(seed):
    random.seed(seed)
    seq=init_seq()
    cur=score_struct(fold(''.join(seq)))
    best=cur; bestseq=seq[:]
    T=3.0
    for it in range(1500):
        s=seq[:]
        r=random.random()
        if r<0.55:
            i=random.choice(paired_i)
            b=random.choice(['G','C','A','U'])
            s[i]=b; s[pair[i]]=comp[b]
        else:
            i=random.choice(unpaired)
            if i not in loopset:
                s[i]=random.choice(['A','C','G','U'])
        d=score_struct(fold(''.join(s)))
        de=d-cur
        if de<=0 or random.random()<pow(2.71828,-de/T):
            seq=s; cur=d
            if d<best:
                best=d; bestseq=s[:]
                if d==0: return best,''.join(bestseq)
        T*=0.9985
        if T<0.05: T=0.05
    return best,''.join(bestseq)

if __name__=='__main__':
    t0=time.time()
    OUT='/tmp/rna_best.txt'
    best_overall=10**9; best_seq=None
    with Pool(24) as p:
        for b,bs in p.imap_unordered(search_worker, range(48), chunksize=1):
            if b<best_overall:
                best_overall=b; best_seq=bs
                with open(OUT,'w') as f:
                    f.write(f"{b}\n{bs}\n")
                print("newbest",b,"time",round(time.time()-t0,1),flush=True)
            if b==0:
                print("SOLVED",flush=True); break
    print("FINAL best",best_overall,"time",round(time.time()-t0,1),flush=True)
    print(best_seq,flush=True)
